const x=$input.item.json||{};
const t=((x.title||'')+' '+(x.description||'')+' '+JSON.stringify(x.economics||{})).toLowerCase();
const flags=[];
const add=(f,rx)=>{if(rx.test(t))flags.push(f)};
add('custody_or_withdrawal_risk',/custody|withdraw|withdrawal|lock|locked|vesting|cliff|claim/);
add('capital_at_risk',/deposit|stake|staking|borrow|leverage|margin|liquidat|collateral|investment|capital|required/);
add('market_liquidity_risk',/low liquidity|thin liquidity|illiquid|slippage|volatile|volatility/);
add('counterparty_risk',/unknown issuer|anonymous team|counterparty|escrow|unverified seller/);
add('scam_or_impersonation_signal',/guaranteed profit|double your|send .*receive|seed phrase|private key|password|impersonat|fake support|wallet connect/);
add('security_exploit_signal',/exploit|drainer|malware|phishing|credential|session token/);
add('regulatory_or_eligibility_review',/kyc|restricted jurisdiction|sanction|regulated|license|accredited|eligibility/);
add('automation_barrier',/captcha|anti.?sybil|proof of humanity|human verification|login required/);

const hardBlock=flags.some(f=>['scam_or_impersonation_signal','security_exploit_signal'].includes(f));
const highRisk=flags.length>=2||flags.includes('capital_at_risk')||flags.includes('custody_or_withdrawal_risk');
const riskTier=hardBlock?'RED':highRisk?'HIGH':flags.length?'AMBER':'GREEN';
const evidence=x.research_plan?.evidence_gaps||[];
const withdrawalCheck=flags.includes('custody_or_withdrawal_risk')||flags.includes('capital_at_risk');

const econ=x.economic_score??x.economics?.economic_score??0;
const budget=Number(x.economics?.budget??x.gross_budget??x.reward_usd??0)||0;
const effort=Number(x.economics?.hours??x.estimated_hours??x.hours??0)||0;
const urgency=/deadline|ends|ending|expires|expir|limited time|first come|closing soon|today|24h|48h|72h/i.test(t);
const rare=/exclusive|rare|limited|invite.?only|early access|undervalued|mispriced|uncrowded|few slots|first come/i.test(t);
const collectible=/claim|payout|paid|payment|reward|bounty|grant|allocation|distribution|withdraw/i.test(t);
const paymentReady=/usdc|usdt|dai|btc|eth|sol|crypto|stablecoin|on.?chain|wallet|bank transfer|paypal/i.test(t);
const sourceReliability=Math.max(0,Math.min(100,Number(x.source_reliability??(x.evidence?.source_reliability||0))||0));
const evidenceQuality=Math.max(0,Math.min(100,Number(x.evidence_quality_score??x.evidence?.fused_evidence_quality??x.evidence?.evidence_quality??0)||0));
const capital=Math.max(0,Number(x.capital_required??x.economics?.capital_required??0)||0);

let value=Math.max(0,Math.min(100,Number(econ)||0));
if(budget>0)value+=Math.min(18,Math.log10(budget+1)*6);
if(urgency)value+=8;
if(rare)value+=7;
if(collectible)value+=7;
if(paymentReady)value+=5;
if(sourceReliability>=70)value+=5;
if(evidenceQuality>=70)value+=5;
if(effort>0)value-=Math.min(10,effort/10);
if(capital>0)value-=Math.min(15,Math.log10(capital+1)*4);
if(riskTier==='HIGH')value-=10;
if(riskTier==='RED')value-=35;
if(flags.includes('automation_barrier'))value-=5;
const huntPriority=Math.round(Math.max(0,Math.min(100,value)));
const eliteCandidate=huntPriority>=85&&!hardBlock;
const fastLane=eliteCandidate&&riskTier==='GREEN'?'standard_review':eliteCandidate?'paper_or_manual_review':'normal_review';

return {json:{...x,high_risk_triage:{version:'high-risk-triage-1.1',risk_tier:riskTier,flags:[...new Set(flags)],hard_block:hardBlock,requires_human_review:riskTier!=='GREEN'||evidence.length>0,withdrawal_and_settlement_check:withdrawalCheck?'required':'not_indicated',source_verification_required:riskTier!=='GREEN'||evidence.length>0,allowed_mode:hardBlock?'research_only':riskTier==='HIGH'?'paper_or_manual_review':riskTier==='AMBER'?'assisted_review':'standard_review',must_not_bypass_controls:true,execution_permission:'unchanged',human_approval_required:true,hunt_priority_score:huntPriority,priority_band:eliteCandidate?'ELITE_CANDIDATE':huntPriority>=70?'HIGH_VALUE':huntPriority>=50?'WATCH':'LOW_SIGNAL',fast_lane_mode:fastLane,priority_factors:{economic_score:Number(econ)||0,budget_signal:budget>0,urgency_signal:urgency,rarity_signal:rare,collectability_signal:collectible,payment_ready_signal:paymentReady,evidence_quality:evidenceQuality,source_reliability:sourceReliability,estimated_effort_hours:effort,capital_required:capital,risk_tier:riskTier},note:'100x target is a prioritization ceiling, not a profit guarantee; no bypass, unauthorized access, auto-claim, or autonomous fund movement.'}}};

